# The layout as it stands: single crews run Development and Production, and the
# joint groups run Longhole and Logistics. Groups are added and changed from here on.
GROUPS = {'AB': ['A', 'B'], 'CD': ['C', 'D']}
SINGLE_DISCIPLINES = ['Development', 'Production']
GROUP_DISCIPLINES = ['Longhole', 'Logistics']


def seed_groups(apps, schema_editor):
    Crews = apps.get_model('timesheets', 'Crews')
    CrewGroup = apps.get_model('timesheets', 'CrewGroup')
    CrewGroupMember = apps.get_model('timesheets', 'CrewGroupMember')
    UnitDiscipline = apps.get_model('timesheets', 'UnitDiscipline')
    Discipline = apps.get_model('timesheets', 'Discipline')

    crews = {c.crewname: c for c in Crews.objects.all()}
    disciplines = {d.name: d for d in Discipline.objects.all()}

    for name in ['A', 'B', 'C', 'D']:
        if name in crews:
            for dname in SINGLE_DISCIPLINES:
                if dname in disciplines:
                    UnitDiscipline.objects.get_or_create(crew=crews[name], discipline=disciplines[dname])

    for gname, members in GROUPS.items():
        group, _ = CrewGroup.objects.get_or_create(groupname=gname)
        for mname in members:
            if mname in crews:
                CrewGroupMember.objects.get_or_create(group=group, crew=crews[mname])
        for dname in GROUP_DISCIPLINES:
            if dname in disciplines:
                UnitDiscipline.objects.get_or_create(group=group, discipline=disciplines[dname])


